const sab = new SharedArrayBuffer(8);
const lock = new Int32Array(sab, 0, 1);
const state = new Int32Array(sab, 4, 1);

function withLock(fn) {
    while (Atomics.compareExchange(lock, 0, 0, 1) !== 0) Atomics.wait(lock, 0, 1);
    try { return fn(); }
    finally { Atomics.store(lock, 0, 0); Atomics.notify(lock, 0, 1); }
}

function awaitState(pred) { while (!pred(Atomics.load(state, 0))) Atomics.wait(state, 0, Atomics.load(state, 0)); }
